srcDoc.css:
body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  color: #111827;
  background: transparent;
}

.login-help {
  padding: 22px;
  box-sizing: border-box;
  background: #fff;
}

.header {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  margin-bottom: 20px;
}

.logo {
  width: 46px;
  height: 46px;
  border-radius: 12px;
  background: #111827;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
}

.eyebrow {
  color: #2563eb;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

h1 {
  margin: 3px 0 4px;
  font-size: 24px;
}

p {
  margin: 0;
  color: #667085;
  font-size: 13px;
}

.cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.card {
  border: 1px solid #d0d5dd;
  border-radius: 9px;
  background: #f9fafb;
  padding: 14px;
  text-align: left;
  cursor: pointer;
}

.card:hover {
  border-color: #2563eb;
  background: #eff6ff;
}

.card strong {
  display: block;
  font-size: 15px;
}

.card span {
  display: block;
  margin-top: 5px;
  color: #667085;
  font-size: 12px;
  line-height: 1.4;
}

.contact {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 18px;
}

.contact div {
  border: 1px solid #d0d5dd;
  border-radius: 9px;
  padding: 12px;
}

.contact span {
  display: block;
  color: #667085;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 800;
}

.contact strong {
  display: block;
  margin-top: 4px;
  font-size: 13px;
}

@media (max-width: 680px) {
  .cards,
  .contact {
    grid-template-columns: 1fr;
  }
}

srcDoc.js:
function render(model = {}) {
  document.getElementById("supportEmail").innerText = model.supportEmail || "-";
  document.getElementById("supportPhone").innerText = model.supportPhone || "-";
  document.querySelectorAll(".card").forEach(card => {
    card.onclick = () => {
      appsmith.updateModel({
        selectedAction: card.dataset.action
      });
      appsmith.triggerEvent("onLoginHelpAction");
    };
  });
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

